sources.core.cod:
type Entity;
type Weighted <: Entity;
function score(x::Entity)::i64 { 1 }
function score(x::Weighted)::i64 { 2 }
function relay(x::Entity)::i64 { score(x) }
function nested(x::Entity)::i64 { relay(x) }
function relay_weighted(x::Weighted)::i64 { score(x) }

sources.adapter.cod:
import "data.cod" Node;
using "core.cod" Weighted;
data Node <: Weighted;

sources.main.cod:
using symbol "std:io" @print;
using "reexport.cod" Packet as Node;
symbol @arena::region;
effect @arena <- region(4096u64);
{ let x = deref(alloc @arena Node(7));
behave @print(score(x));
behave @print(relay(x));
behave @print(nested(x));
behave @print(relay_weighted(x));
};

